import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="3mo",progress=False,auto_adjust=True); close=data["Close"]; volume=data["Volume"]; print("\n".join((lambda p,p5,mm20,v,vm20,s:f"{t}: {p:.2f} | Var 5j: {p5:+.2f}% | MM20: {mm20:.2f} | Volume: {v:.0f}/{vm20:.0f} | Score: {s}/100 | Signal: {'ACHAT' if s>=70 else 'SURVEILLANCE' if s>=40 else 'AUCUN SIGNAL'}")(float(close[t].iloc[-1]),(float(close[t].iloc[-1])/float(close[t].iloc[-6])-1)*100,float(close[t].tail(20).mean()),float(volume[t].iloc[-1]),float(volume[t].tail(20).mean()),(40 if float(close[t].iloc[-1])>float(close[t].tail(20).mean()) else 0)+(30 if float(volume[t].iloc[-1])>float(volume[t].tail(20).mean()) else 0)+(30 if (float(close[t].iloc[-1])/float(close[t].iloc[-6])-1)*100>3 else 0)) for t in tickers if t in close.columns and close[t].dropna().shape[0]>=20))
